#pragma once

#include <string>
#include <vector>
#include <cstdint>

// Generic structure to receive contiguous blocks of bytes from Pass 2.
// Each block represents a segment of code without memory gaps.
struct ObjectBlock {
    uint32_t address;
    std::vector<uint8_t> bytes;
};

// Structure to receive relocations (modifications) generated by Pass 2.
// Used for the M Record (mostly for format 4 addresses).
struct ModificationRecord {
    uint32_t address;
    uint8_t halfBytes; // Length in half-bytes (usually 5 for format 4)
};

// Main class responsible for formatting the SIC/XE object program
class ObjectProgram {
private:
    std::string name;
    uint32_t startAddress;
    uint32_t programSize;
    uint32_t executionAddress;
    
    std::vector<ObjectBlock> blocks;
    std::vector<ModificationRecord> modifications;

public:
    // Constructor that receives the information for the H and E records
    ObjectProgram(const std::string& progName, uint32_t start, uint32_t size, uint32_t execAddr);

    // Methods for Pass 2 to inject the generated data
    void addBlock(const ObjectBlock& block);
    void addModification(const ModificationRecord& mod);
    
    // Returns all internal blocks (useful for SimulatorBridge to read later)
    const std::vector<ObjectBlock>& getBlocks() const;

    // Generates the final string containing all records (H, T, M, E) with line breaks
    std::string toText() const;
};